CodeAssembler& CodeAssemblerFns4::vdivpd(AsmRegisterXmm op0, AsmRegisterXmm op1, AsmMemoryOperand op2) {
	Code code;
	if (op2.is_broadcast()) {
		code = Code::EVEX_Vdivpd_xmm_k1z_xmm_xmmm128b64;
	} else if (instruction_prefer_vex()) {
		code = Code::VEX_Vdivpd_xmm_xmm_xmmm128;
	} else {
		code = Code::EVEX_Vdivpd_xmm_k1z_xmm_xmmm128b64;
	}
	return add_instr_with_state(Instruction::with3(code, op0.register_(), op1.register_(), to_memory_operand(op2)), op0.state().merge(op2.state()));
}

